class ObserverEdgeGuard final {
public:
    explicit ObserverEdgeGuard(TrackedCriticalSection* section) : section_(section) {
        if (section_) {
            EnterCriticalSection(&section_->native);
            add_depth(1u);
        }
    }
    ~ObserverEdgeGuard() {
        if (section_) {
            add_depth(0xffffffffu);
            LeaveCriticalSection(&section_->native);
        }
